const nextInvoiceNumber = `-- name: NextInvoiceNumber :one

INSERT INTO billing_invoice_counters (series, year, last_no)
VALUES ($1, $2, 1)
ON CONFLICT (series, year) DO UPDATE SET last_no = billing_invoice_counters.last_no + 1
RETURNING last_no
`

type NextInvoiceNumberParams struct {
	Series string `json:"series"`
	Year   int32  `json:"year"`
}

// Billing invoices, invoice profiles and seller/XSLT settings.
// Single atomic upsert: row lock on conflict serialises concurrent callers.
func (q *Queries) NextInvoiceNumber(ctx context.Context, arg NextInvoiceNumberParams) (int64, error) {
	row := q.db.QueryRow(ctx, nextInvoiceNumber, arg.Series, arg.Year)
	var last_no int64
	err := row.Scan(&last_no)
	return last_no, err
}

